/**
 * ER-07-04: character course fixture (07 §3.5, §5.8).
 *
 * One kinematic capsule on a flat ground plane runs five scenarios in order:
 * a 45° ramp with a 40° slope limit (horizontal motion must stop), a 0.3 m
 * step (must be climbed), a 2 m drop (must land grounded), a vertical wall
 * (penetration ≤ 0.02 m) and a flat ceiling (must be detected). Values in
 * `recorded` are generated by this test, not invented.
 */
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, test } from "vitest";
import type { Vec3 } from "@lanpad/engine-core";
import type { CharacterController } from "../../src/index.js";
import {
  DT,
  bodyState,
  ground,
  init,
  makeWorld,
  q,
  staticBox,
  v3,
} from "../support/world.js";

interface CharacterFixture {
  readonly world: {
    readonly gravity: readonly number[];
  };
  readonly character: {
    readonly radius: number;
    readonly halfHeight: number;
    readonly slopeLimitDegrees: number;
    readonly stepOffset: number;
    readonly snapToGround: number;
    readonly gravity: number;
    readonly moveSpeed: number;
  };
  readonly course: {
    readonly ground: {
      readonly top: number;
      readonly halfExtents: readonly number[];
    };
    readonly ramp: {
      readonly center: readonly number[];
      readonly halfExtents: readonly number[];
      readonly rotation: readonly number[];
      readonly start: readonly number[];
    };
    readonly step: {
      readonly center: readonly number[];
      readonly halfExtents: readonly number[];
      readonly start: readonly number[];
    };
    readonly drop: {
      readonly start: readonly number[];
      readonly heightM: number;
    };
    readonly wall: {
      readonly center: readonly number[];
      readonly halfExtents: readonly number[];
      readonly faceX: number;
      readonly start: readonly number[];
    };
    readonly ceiling: {
      readonly center: readonly number[];
      readonly halfExtents: readonly number[];
      readonly bottomY: number;
      readonly start: readonly number[];
    };
  };
  readonly control: {
    readonly rampPushTicks: number;
    readonly rampMeasureTicks: number;
    readonly stepWalkTicks: number;
    readonly dropMaxTicks: number;
    readonly wallPushTicks: number;
    readonly ceilingPushTicks: number;
    readonly ceilingPushPerTick: number;
  };
  readonly recorded: {
    readonly rampHitWallTick: number | null;
    readonly rampHorizontalAdvanceM: number | null;
    readonly rampVerticalAdvanceM: number | null;
    readonly stepFinalX: number | null;
    readonly stepClimbedY: number | null;
    readonly stepGrounded: boolean | null;
    readonly dropLandingTick: number | null;
    readonly dropFinalY: number | null;
    readonly wallHitSeen: boolean | null;
    readonly wallMaxPenetrationM: number | null;
    readonly ceilingHitSeen: boolean | null;
    readonly ceilingMaxHeadY: number | null;
    readonly ceilingPenetrationM: number | null;
    readonly finalHash: number | null;
  };
}

const fixture = JSON.parse(
  readFileSync(
    new URL("../fixtures/character-course.json", import.meta.url),
    "utf8",
  ),
) as CharacterFixture;

function at(values: readonly number[]): Vec3 {
  return v3(values[0]!, values[1]!, values[2]!);
}

beforeAll(async () => {
  await init();
});

describe("character-course fixture", () => {
  test(
    "[ER-07-04] the capsule is blocked by a 45° ramp, climbs a 0.3 m step, lands from 2 m, slides a wall and hits a ceiling",
    () => {
      const world = makeWorld({
        gravity: v3(
          fixture.world.gravity[0]!,
          fixture.world.gravity[1]!,
          fixture.world.gravity[2]!,
        ),
      });
      const course = fixture.course;
      ground(
        world,
        course.ground.top,
        v3(
          course.ground.halfExtents[0]!,
          course.ground.halfExtents[1]!,
          course.ground.halfExtents[2]!,
        ),
        { friction: 0.9 },
      );
      staticBox(world, at(course.ramp.center), at(course.ramp.halfExtents), {
        friction: 0.9,
        localRotation: q(
          course.ramp.rotation[0]!,
          course.ramp.rotation[1]!,
          course.ramp.rotation[2]!,
          course.ramp.rotation[3]!,
        ),
      });
      staticBox(world, at(course.step.center), at(course.step.halfExtents), {
        friction: 0.9,
      });
      staticBox(world, at(course.wall.center), at(course.wall.halfExtents), {
        friction: 0.9,
      });
      staticBox(
        world,
        at(course.ceiling.center),
        at(course.ceiling.halfExtents),
        { friction: 0.9 },
      );

      const cfg = fixture.character;
      const character: CharacterController = world.createCharacter({
        radius: cfg.radius,
        halfHeight: cfg.halfHeight,
        position: at(course.ramp.start),
        slopeLimitDegrees: cfg.slopeLimitDegrees,
        stepOffset: cfg.stepOffset,
        snapToGround: cfg.snapToGround,
        gravity: cfg.gravity,
      });
      const body = bodyState();
      const control = fixture.control;
      const forward = v3(0.05, 0, 0);
      const stepOnce = (
        desired: Vec3,
      ): { grounded: boolean; hitWall: boolean; hitCeiling: boolean } => {
        const result = character.move(desired, DT);
        const flags = {
          grounded: result.grounded,
          hitWall: result.hitWall,
          hitCeiling: result.hitCeiling,
        };
        world.step(DT);
        world.readBody(character.body, body);
        return flags;
      };

      /* 45° ramp: push +X until blocked, then measure 60 more ticks. */
      character.teleport(at(course.ramp.start));
      let rampHitWallTick = -1;
      let rampStartX = 0;
      let rampStartY = 0;
      let measured = 0;
      for (let tick = 0; tick < control.rampPushTicks; tick += 1) {
        const flags = stepOnce(forward);
        if (rampHitWallTick < 0 && flags.hitWall) {
          rampHitWallTick = tick;
          rampStartX = body.position.x;
          rampStartY = body.position.y;
        }
        if (rampHitWallTick >= 0 && tick >= rampHitWallTick) {
          measured += 1;
          if (measured >= control.rampMeasureTicks) break;
        }
      }
      const rampHorizontalAdvanceM = body.position.x - rampStartX;
      const rampVerticalAdvanceM = body.position.y - rampStartY;

      /* 0.3 m step: walk +X and climb onto the top surface. */
      character.teleport(at(course.step.start));
      let stepFlags = stepOnce(forward);
      for (let tick = 1; tick < control.stepWalkTicks; tick += 1) {
        stepFlags = stepOnce(forward);
      }
      const stepFinalX = body.position.x;
      const stepClimbedY = body.position.y;
      const stepGrounded = stepFlags.grounded;

      /* 2 m drop: gravity only, wait for grounded. */
      character.teleport(at(course.drop.start));
      let dropLandingTick = -1;
      for (let tick = 0; tick < control.dropMaxTicks; tick += 1) {
        const flags = stepOnce(v3(0, 0, 0));
        if (flags.grounded && body.position.y < 1) {
          dropLandingTick = tick;
          break;
        }
      }
      const dropFinalY = body.position.y;

      /* Vertical wall: measure the deepest capsule-face penetration. */
      character.teleport(at(course.wall.start));
      let wallHitSeen = false;
      let wallMaxPenetrationM = -Infinity;
      for (let tick = 0; tick < control.wallPushTicks; tick += 1) {
        const flags = stepOnce(forward);
        wallHitSeen = wallHitSeen || flags.hitWall;
        wallMaxPenetrationM = Math.max(
          wallMaxPenetrationM,
          body.position.x + cfg.radius - course.wall.faceX,
        );
      }

      /* Flat ceiling: push up until the capsule head contacts it. */
      character.teleport(at(course.ceiling.start));
      let ceilingHitSeen = false;
      let ceilingMaxHeadY = -Infinity;
      for (let tick = 0; tick < control.ceilingPushTicks; tick += 1) {
        const flags = stepOnce(v3(0, control.ceilingPushPerTick, 0));
        ceilingHitSeen = ceilingHitSeen || flags.hitCeiling;
        ceilingMaxHeadY = Math.max(
          ceilingMaxHeadY,
          body.position.y + cfg.halfHeight + cfg.radius,
        );
      }
      const ceilingPenetrationM =
        ceilingMaxHeadY - course.ceiling.bottomY;
      const finalHash = world.stateHash();

      expect(rampHitWallTick).toBeGreaterThanOrEqual(0);
      expect(rampHorizontalAdvanceM).toBeLessThanOrEqual(0.1);
      expect(rampVerticalAdvanceM).toBeLessThanOrEqual(0.1);
      expect(stepFinalX).toBeGreaterThanOrEqual(6.5);
      expect(stepClimbedY).toBeGreaterThanOrEqual(1.15);
      expect(stepGrounded).toBe(true);
      expect(dropLandingTick).toBeGreaterThanOrEqual(0);
      expect(Math.abs(dropFinalY - 0.9)).toBeLessThanOrEqual(0.02);
      expect(wallHitSeen).toBe(true);
      expect(wallMaxPenetrationM).toBeLessThanOrEqual(0.02);
      expect(ceilingHitSeen).toBe(true);
      expect(ceilingPenetrationM).toBeLessThanOrEqual(0.02);

      const recorded = fixture.recorded;
      if (recorded.rampHitWallTick !== null) {
        expect(rampHitWallTick).toBe(recorded.rampHitWallTick);
      }
      if (recorded.rampHorizontalAdvanceM !== null) {
        expect(rampHorizontalAdvanceM).toBeCloseTo(
          recorded.rampHorizontalAdvanceM,
          5,
        );
      }
      if (recorded.rampVerticalAdvanceM !== null) {
        expect(rampVerticalAdvanceM).toBeCloseTo(
          recorded.rampVerticalAdvanceM,
          5,
        );
      }
      if (recorded.stepFinalX !== null) {
        expect(stepFinalX).toBeCloseTo(recorded.stepFinalX, 5);
      }
      if (recorded.stepClimbedY !== null) {
        expect(stepClimbedY).toBeCloseTo(recorded.stepClimbedY, 5);
      }
      if (recorded.stepGrounded !== null) {
        expect(stepGrounded).toBe(recorded.stepGrounded);
      }
      if (recorded.dropLandingTick !== null) {
        expect(dropLandingTick).toBe(recorded.dropLandingTick);
      }
      if (recorded.dropFinalY !== null) {
        expect(dropFinalY).toBeCloseTo(recorded.dropFinalY, 5);
      }
      if (recorded.wallHitSeen !== null) {
        expect(wallHitSeen).toBe(recorded.wallHitSeen);
      }
      if (recorded.wallMaxPenetrationM !== null) {
        expect(wallMaxPenetrationM).toBeCloseTo(
          recorded.wallMaxPenetrationM,
          5,
        );
      }
      if (recorded.ceilingHitSeen !== null) {
        expect(ceilingHitSeen).toBe(recorded.ceilingHitSeen);
      }
      if (recorded.ceilingMaxHeadY !== null) {
        expect(ceilingMaxHeadY).toBeCloseTo(
          recorded.ceilingMaxHeadY,
          5,
        );
      }
      if (recorded.ceilingPenetrationM !== null) {
        expect(ceilingPenetrationM).toBeCloseTo(
          recorded.ceilingPenetrationM,
          5,
        );
      }
      if (recorded.finalHash !== null) {
        expect(finalHash).toBe(recorded.finalHash);
      }
      console.log(
        `[record character-course] rampHitWallTick=${rampHitWallTick} rampHorizontalAdvanceM=${rampHorizontalAdvanceM} rampVerticalAdvanceM=${rampVerticalAdvanceM} stepFinalX=${stepFinalX} stepClimbedY=${stepClimbedY} stepGrounded=${stepGrounded} dropLandingTick=${dropLandingTick} dropFinalY=${dropFinalY} wallHitSeen=${wallHitSeen} wallMaxPenetrationM=${wallMaxPenetrationM} ceilingHitSeen=${ceilingHitSeen} ceilingMaxHeadY=${ceilingMaxHeadY} ceilingPenetrationM=${ceilingPenetrationM} finalHash=${finalHash}`,
      );
      world.dispose();
    },
    120_000,
  );
});
